products.css:
/*===== VIDEO ONE =====*/
.video-one {
  background-color: var(--light-2);
  padding-top: 120px;
  padding-bottom: 100px;
}
.video-one .video-title h5 {
  font-weight: 600;
  color: var(--primary);
}
.video-one .video-title h2 {
  font-weight: 700;
  color: var(--black);
  margin-top: 10px;
}
.video-one .video-title .text-lg {
  margin-top: 24px;
  color: var(--dark-3);
}
.video-one .video-content {
  position: relative;
  margin-top: 60px;
  border-radius: 8px;
  overflow: hidden;
}
.video-one .video-content img {
  border-radius: 8px;
}
.video-one .video-content a {
  width: 88px;
  height: 88px;
  line-height: 88px;
  text-align: center;
  border-radius: 50%;
  background-color: var(--primary);
  color: var(--white);
  font-size: 30px;
  position: absolute;
  top: 50%;
  left: 50%;
  -webkit-transform: translate(-50%, -50%);
  -moz-transform: translate(-50%, -50%);
  -ms-transform: translate(-50%, -50%);
  -o-transform: translate(-50%, -50%);
  transform: translate(-50%, -50%);
  -webkit-transition: all 0.3s ease-out 0s;
  -moz-transition: all 0.3s ease-out 0s;
  -ms-transition: all 0.3s ease-out 0s;
  -o-transition: all 0.3s ease-out 0s;
  transition: all 0.3s ease-out 0s;
  padding-left: 3px;
}
@media (max-width: 767px) {
  .video-one .video-content a {
    width: 68px;
    height: 68px;
    line-height: 68px;
    font-size: 46px;
  }
}
.video-one .video-content a:hover {
  background-color: var(--white);
  color: var(--primary);
}

/*===== VIDEO STYLE 2 =====*/
.primary-btn { background: var(--secondary); color: var(--white); box-shadow: var(--shadow-2); padding: 12px 26px; border-radius: 6px; font-weight: 600; border: none; }
.primary-btn:hover { background: var(--secondary-dark); color: var(--white); box-shadow: var(--shadow-4); }
.outline-btn { border: 1.5px solid var(--secondary); color: var(--secondary); padding: 11px 24px; border-radius: 6px; font-weight: 600; background: transparent; }
.outline-btn:hover { background: var(--secondary); color: var(--white); }
.videos-style-3 { background: var(--light-2); padding: 70px 0; }
.videos-style-3 .section-box { background: var(--white); border: 1px solid var(--gray-4); border-radius: 16px; padding: 42px 34px; box-shadow: var(--shadow-2); }
.videos-style-3 .tag-label { color: var(--secondary); font-size: 13px; font-weight: 700; letter-spacing: .06em; }
.videos-style-3 h2, .videos-style-3 h5 { color: var(--black); }
.videos-style-3 p { color: var(--dark-2); }
.videos-style-3 .mini-card { padding: 24px; border-radius: 12px; background: var(--light-2); border: 1px solid var(--gray-4); height: 100%; }
.videos-style-3 .mini-card i { color: var(--secondary); }

/*===== VIDEO STYLE 3 =====*/
.primary-btn { background: var(--accent); color: var(--white); box-shadow: var(--shadow-2); padding: 12px 26px; border-radius: 6px; font-weight: 600; border: none; }
.primary-btn:hover { background: var(--accent-dark); color: var(--white); box-shadow: var(--shadow-4); }
.outline-btn { border: 1.5px solid var(--accent); color: var(--white); padding: 11px 24px; border-radius: 6px; font-weight: 600; background: transparent; }
.outline-btn:hover { background: var(--accent); color: var(--white); }
.videos-style-4 { background: var(--dark-1); padding: 70px 0; }
.videos-style-4 .section-box { background: #383838; border: 1px solid #4d4d4d; border-radius: 16px; padding: 42px 34px; box-shadow: var(--shadow-2); }
.videos-style-4 .tag-label { color: var(--accent); font-size: 13px; font-weight: 700; letter-spacing: .06em; }
.videos-style-4 h2, .videos-style-4 h5 { color: var(--white); }
.videos-style-4 p { color: var(--gray-3); }
.videos-style-4 .mini-card { padding: 24px; border-radius: 12px; background: var(--dark-1); border: 1px solid #4d4d4d; height: 100%; }
.videos-style-4 .mini-card i { color: var(--accent); }
